python - <<'EOF'
p='Collection.cs'
s=open(p).read()
i=s.rindex('}')
add='''
    [GrasshopperCollection("Bench", "Fabrication")]
    public interface IFabricationPack : IBettaCollection
    {
        [GrasshopperMethod("Shelf Pack", "Packs rectangular parts onto rectangular sheets with a shelf algorithm")]
        (System.Collections.Generic.List<Rhino.Geometry.Curve> Outlines,
            System.Collections.Generic.List<int> Sheet,
            int SheetCount,
            double Utilization,
            System.Collections.Generic.List<int> Unplaced) ShelfPack(
            [GrasshopperParameter("Widths")] System.Collections.Generic.List<double> widths,
            [GrasshopperParameter("Heights")] System.Collections.Generic.List<double> heights,
            [GrasshopperParameter("Sheet Width", DefaultValue = 1000.0)] double sheetWidth,
            [GrasshopperParameter("Sheet Height", DefaultValue = 500.0)] double sheetHeight,
            [GrasshopperParameter("Spacing", DefaultValue = 5.0)] double spacing,
            [GrasshopperParameter("Rotate", DefaultValue = true)] bool rotate,
            IBettaReport report);
    }

    public class FabricationPack : IFabricationPack
    {
        public (System.Collections.Generic.List<Rhino.Geometry.Curve> Outlines,
            System.Collections.Generic.List<int> Sheet,
            int SheetCount,
            double Utilization,
            System.Collections.Generic.List<int> Unplaced) ShelfPack(
            System.Collections.Generic.List<double> widths,
            System.Collections.Generic.List<double> heights,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            bool rotate,
            IBettaReport report)
        {
            widths ??= new System.Collections.Generic.List<double>();
            heights ??= new System.Collections.Generic.List<double>();
            if (widths.Count != heights.Count)
                throw new System.ArgumentException("Widths and Heights must have the same length.");
            if (sheetWidth <= 0 || sheetHeight <= 0)
                throw new System.ArgumentException("Sheet size must be positive.");
            if (spacing < 0)
                throw new System.ArgumentException("Spacing must not be negative.");
            for (int i = 0; i < widths.Count; i++)
                if (widths[i] <= 0 || heights[i] <= 0)
                    throw new System.ArgumentException("All part sizes must be greater than zero.");

            var outlines = new System.Collections.Generic.List<Rhino.Geometry.Curve>();
            var sheets = new System.Collections.Generic.List<int>();
            var unplaced = new System.Collections.Generic.List<int>();

            bool FitsEmpty(double w, double h) =>
                w + 2 * spacing <= sheetWidth && h + 2 * spacing <= sheetHeight;

            var order = new System.Collections.Generic.List<int>();
            for (int i = 0; i < widths.Count; i++) order.Add(i);
            order.Sort((a, b) =>
            {
                int c = heights[b].CompareTo(heights[a]);
                return c != 0 ? c : a.CompareTo(b);
            });

            int sheet = -1;
            double x = 0, shelfY = 0, shelfH = 0;
            double placedArea = 0;

            void Add(int index, double w, double h, double px, double py)
            {
                double ox = sheet * (sheetWidth + 50);
                var rect = new Rhino.Geometry.Polyline(new[]
                {
                    new Rhino.Geometry.Point3d(ox + px, py, 0),
                    new Rhino.Geometry.Point3d(ox + px + w, py, 0),
                    new Rhino.Geometry.Point3d(ox + px + w, py + h, 0),
                    new Rhino.Geometry.Point3d(ox + px, py + h, 0),
                    new Rhino.Geometry.Point3d(ox + px, py, 0),
                });
                outlines.Add(rect.ToPolylineCurve());
                sheets.Add(sheet);
                placedArea += w * h;
            }

            foreach (int i in order)
            {
                double w = widths[i], h = heights[i];
                if (!FitsEmpty(w, h) && !(rotate && FitsEmpty(h, w)))
                {
                    unplaced.Add(i);
                    continue;
                }

                // current shelf
                if (sheet >= 0)
                {
                    bool asIs = x + w + spacing <= sheetWidth && h <= shelfH;
                    bool turned = rotate && x + h + spacing <= sheetWidth && w <= shelfH;
                    if (asIs || turned)
                    {
                        if (!asIs) (w, h) = (h, w);
                        Add(i, w, h, x, shelfY);
                        x += w + spacing;
                        continue;
                    }

                    // new shelf on the current sheet
                    double y = shelfY + shelfH + spacing;
                    bool shelfAsIs = w + 2 * spacing <= sheetWidth && y + h + spacing <= sheetHeight;
                    bool shelfTurned = rotate && h + 2 * spacing <= sheetWidth && y + w + spacing <= sheetHeight;
                    if (shelfAsIs || shelfTurned)
                    {
                        if (!shelfAsIs) (w, h) = (h, w);
                        shelfY = y;
                        shelfH = h;
                        Add(i, w, h, spacing, shelfY);
                        x = spacing + w + spacing;
                        continue;
                    }
                }

                // new sheet
                if (!FitsEmpty(w, h)) (w, h) = (h, w);
                sheet++;
                shelfY = spacing;
                shelfH = h;
                Add(i, w, h, spacing, shelfY);
                x = spacing + w + spacing;
            }

            int sheetCount = sheet + 1;
            double utilization = sheetCount == 0 ? 0 : placedArea / (sheetCount * sheetWidth * sheetHeight);

            if (unplaced.Count > 0)
            {
                unplaced.Sort();
                report.Warning($"{unplaced.Count} part(s) did not fit on a sheet and were left out.");
            }

            return (outlines, sheets, sheetCount, utilization, unplaced);
        }
    }
'''
open(p,'w').write(s[:i]+add+s[i:])
EOF
dotnet build 2>&1 | tail -8
